oxy_webhelp_navlinks = {"okta_idp-d39536e60143":{"topics":[{"title":"Introduction to Okta protection","href":"okta\/okta_key_features_protection.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e60156","next":"tocId-d39536e60156"},{"title":"Plan your Okta IdP protection","shortdesc":"<p class=\"shortdesc\">Before integrating Okta IdP with <span class=\"ph\">RSC<\/span>, you must meet certain         requirements to start protecting your critical Okta objects.<\/p>","href":"okta\/plan_okta_idp_protection.html","attributes":{"data-id":"plan_okta_idp_protection"},"menu":{"hasChildren":false},"tocID":"plan_okta_idp_protection-d39536e60181","next":"plan_okta_idp_protection-d39536e60181"},{"title":"Evaluate Okta configuration options","shortdesc":"<p class=\"shortdesc\">You can add Okta tenants to <span class=\"ph\">RSC<\/span> using the Identity Resilience         inventory, Data Protection inventory, or Settings menu.<\/p>","href":"okta\/evaluate_okta_configuration_options.html","attributes":{"data-id":"evaluate_okta_configuration_options"},"menu":{"hasChildren":false},"tocID":"evaluate_okta_configuration_options-d39536e60232","topics":[]},{"title":"Configure Okta IdP","shortdesc":"<p class=\"shortdesc\">Configure your Okta Identity Provider by adding Okta tenants to <span class=\"ph\">RSC<\/span>         and perform other maintenance operations, such as editing and removing the Okta         tenants.<\/p>","href":"okta\/configure_okta_idp.html","attributes":{"data-id":"configure_okta_idp"},"menu":{"hasChildren":false},"tocID":"configure_okta_idp-d39536e60246","next":"configure_okta_idp-d39536e60246"},{"title":"Manage protection for Okta IdP","shortdesc":"<p class=\"shortdesc\">You can use SLA Domains to apply data protection and management policies to Okta         tenants for optimal protection.<\/p>","href":"okta\/manage_protection_okta_idp.html","attributes":{"data-id":"manage_protection_okta_idp"},"menu":{"hasChildren":false},"tocID":"manage_protection_okta_idp-d39536e60324","next":"manage_protection_okta_idp-d39536e60324"},{"title":"Recover Okta objects","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> recovers individual Okta objects, along with their related         objects and relationships, from automated or on-demand snapshots. You can recover objects to         the same tenant or to a different onboarded tenant.<\/p>","href":"okta\/recover_okta_objects.html","attributes":{"data-id":"recover_okta_objects"},"menu":{"hasChildren":false},"tocID":"recover_okta_objects-d39536e60371","next":"recover_okta_objects-d39536e60371"},{"title":"Manage Okta tenants","shortdesc":"<p class=\"shortdesc\">Viewing and analyzing detailed information about your protected Okta IdP from the         Inventory page enables you to make informed decisions. Key aspects include viewing tenants,         checking protection status, reviewing detailed object attributes, browsing the snapshot         calendar, viewing events log for audit and compliance, and performing maintenance such as         deleting snapshots.<\/p>","href":"okta\/manage_okta_tenants.html","attributes":{"data-id":"manage_okta_tenants"},"menu":{"hasChildren":false},"tocID":"manage_okta_tenants-d39536e60625","next":"manage_okta_tenants-d39536e60625"}]}};